const $=id=>document.getElementById(id), api=async(path,options={})=>{const response=await fetch('/api'+path,{credentials:'same-origin',...options,headers:{...(options.body instanceof FormData?{}:{'Content-Type':'application/json'}),...(options.headers||{})}});let data={};try{data=await response.json()}catch{}if(!response.ok)throw Error(data.detail||`Request failed (${response.status})`);return data};
function toast(message){const e=$('toast');e.textContent=message;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),2800)}function esc(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function showPage(page){document.querySelectorAll('.panel').forEach(x=>x.classList.toggle('active',x.id===page));document.querySelectorAll('.nav button').forEach(x=>x.classList.toggle('active',x.dataset.page===page));$('crumb').textContent={overview:'Overview',matcher:'Job matcher',agents:'Agent search',tracker:'Applications',copilot:'AI copilot',profile:'My profile'}[page]||page;if(page==='agents'){loadSources();loadJobs()}if(page==='tracker')loadApplications();window.scrollTo(0,0)}document.querySelectorAll('.nav button').forEach(b=>b.onclick=()=>showPage(b.dataset.page));
function parseList(value){return value.split(',').map(x=>x.trim()).filter(Boolean)}function setVal(id,value){if($(id))$(id).value=value??''}
async function checkSession(){try{await api('/session');$('loginOverlay')?.classList.add('hidden');await initialize()}catch(e){toast(e.message)}}
async function initialize(){try{await loadProfile();await loadApplications();const s=await api('/status');$('systemState').textContent=`Server active · ${s.job_sources} boards · ${s.sponsor_records} sponsorship records${s.email_configured?' · email ready':''}${s.scheduled_search_configured?' · scheduled search ready':''}`;if(!s.ai_configured)$('aiNotice').textContent='Local draft mode is available. Configure an AI provider on the server only if you want external resume tailoring.'}catch(e){toast(e.message)}}
async function loadProfile(){const {profile:p,resume}=await api('/profile');setVal('pName',p.name);setVal('pEmail',p.email);setVal('pPhone',p.phone);setVal('pLocation',p.location);setVal('pCompany',p.current_company);setVal('pRole',p.role);setVal('pYears',p.years_experience);setVal('pSkills',(p.skills||[]).join(', '));setVal('pEducation',p.education);setVal('pTargets',(p.target_titles||[]).join(', '));setVal('pLocations',(p.location_preferences||[]).join(', '));setVal('pModes',(p.work_modes||[]).join(', '));setVal('pSalary',p.minimum_salary);setVal('pThreshold',p.match_threshold??55);setVal('pVisa',p.work_authorization||p.sponsorship_preferences);setVal('pSummary',p.summary);$('pAlerts').checked=!!p.email_alerts;$('resumeStatus').textContent=resume?`${resume.filename} · uploaded ${new Date(resume.uploaded_at).toLocaleDateString()}`:'No resume uploaded';}
async function saveProfile(){try{const p={name:$('pName').value,email:$('pEmail').value,phone:$('pPhone').value,location:$('pLocation').value,current_company:$('pCompany').value,role:$('pRole').value,years_experience:Number($('pYears').value)||null,skills:parseList($('pSkills').value),education:$('pEducation').value,target_titles:parseList($('pTargets').value),location_preferences:parseList($('pLocations').value),work_modes:parseList($('pModes').value),minimum_salary:Number($('pSalary').value)||null,match_threshold:Number($('pThreshold').value)||55,work_authorization:$('pVisa').value,sponsorship_preferences:$('pVisa').value,summary:$('pSummary').value,email_alerts:$('pAlerts').checked};await api('/profile',{method:'PUT',body:JSON.stringify(p)});toast('Profile saved privately')}catch(e){toast(e.message)}}
async function uploadResume(){const f=$('resumeFile').files[0];if(!f){toast('Choose a PDF or DOCX resume');return}try{const form=new FormData();form.append('file',f);const result=await api('/resume',{method:'POST',body:form});await loadProfile();toast(`Resume saved. Extracted ${result.characters_extracted} characters; review your profile.`)}catch(e){toast(e.message)}}async function importSponsors(){const f=$('sponsorFile').files[0];if(!f){toast('Choose a CSV file');return}try{const form=new FormData();form.append('file',f);const r=await api('/sponsors/import',{method:'POST',body:form});toast(`${r.imported} sponsorship evidence rows imported`)}catch(e){toast(e.message)}}
async function addSource(){try{await api('/sources',{method:'POST',body:JSON.stringify({ats_type:$('sourceType').value,slug:$('sourceSlug').value.trim(),company_name:$('sourceCompany').value.trim()})});$('sourceSlug').value='';$('sourceCompany').value='';await loadSources();toast('Career board added')}catch(e){toast(e.message)}}async function removeSource(id){try{await api(`/sources/${id}`,{method:'DELETE'});await loadSources()}catch(e){toast(e.message)}}async function loadSources(){try{const rows=await api('/sources');$('sourceList').innerHTML=rows.length?rows.map(s=>`<div class="step"><span><strong>${esc(s.company_name)}</strong>${esc(s.ats_type)} / ${esc(s.slug)}</span><button class="btn" onclick="removeSource(${s.id})">Remove</button></div>`).join(''):'<div class="empty">No employer boards configured.</div>'}catch(e){}}
async function runSearch(){const b=document.querySelector('#agents .pagehead .btn');try{if(b){b.disabled=true;b.textContent='Searching…'}const r=await api('/search/run',{method:'POST'});toast(`${r.jobs_saved} new roles saved · ${r.sources_checked} boards checked`);await loadJobs()}catch(e){toast(e.message)}finally{if(b){b.disabled=false;b.textContent='↻ Search now'}}}
async function loadJobs(){try{const rows=await api('/jobs?min_score=0');$('jobCount').textContent=`${rows.length} found`;$('cloudJobs').innerHTML=rows.length?rows.map(j=>`<article class="job"><div class="jobmain"><div class="companymark">${esc(j.company.slice(0,2).toUpperCase())}</div><div><h4>${esc(j.title)} · ${esc(j.company)}</h4><p>${esc(j.location||'Location not stated')} · ${esc(j.work_mode)} · ${esc(j.salary)}</p><p><b>${j.fit_score}% fit</b> · ${esc(j.sponsorship_status)} — ${esc(j.sponsorship_evidence)}</p><p>${esc((j.fit_reasons||[]).join(' · '))}</p><a href="${esc(j.url)}" target="_blank" rel="noopener">Open posting for RPA ↗</a> <button class="btn" onclick="trackJob(${j.id})">Track</button> <button class="btn" onclick="tailorJob(${j.id})">Prepare resume draft</button></div></div></article>`).join(''):'<div class="empty">No jobs found yet. Add employer boards and run a search.</div>'}catch(e){$('cloudJobs').innerHTML='<div class="empty">Sign in to load search results.</div>'}}
async function trackJob(id){try{await api('/applications',{method:'POST',body:JSON.stringify({job_id:id})});toast('Added to your application tracker');await loadApplications()}catch(e){toast(e.message)}}async function tailorJob(id){const useAI=confirm('Use an external AI provider for tailoring? Your resume text and profile will be sent to the provider configured by you on the server. Choose Cancel for a local draft.');try{const r=await api(`/jobs/${id}/tailor`,{method:'POST',body:JSON.stringify({confirmed_resume_use:true,use_external_ai:useAI})});$('draftResult').textContent=r.content;$('draftResult').classList.remove('hidden');showPage('copilot');toast('Draft ready. Review every fact before using it.')}catch(e){toast(e.message)}}
async function loadApplications(){try{const items=await api('/applications');$('statApps').textContent=items.length;$('statAnalyzed').textContent=(await api('/jobs')).length;$('statFit').textContent=items.length?`${Math.max(...items.map(x=>x.job.fit_score))}%`:'—';const stages=['Shortlist','Applied','Interview','Decision'];$('kanban').innerHTML=stages.map(stage=>`<div class="column"><div class="colhead">${stage}<span>${items.filter(x=>x.stage===stage).length}</span></div>${items.filter(x=>x.stage===stage).map(x=>`<div class="jobcard"><b>${esc(x.job.title)}</b><span>${esc(x.job.company)} · ${x.job.fit_score}%</span><br><a href="${esc(x.job.url)}" target="_blank" rel="noopener">Posting ↗</a><br><select onchange="setStage(${x.id},this.value)">${stages.map(s=>`<option ${s===x.stage?'selected':''}>${s}</option>`).join('')}</select></div>`).join('')||'<div class="empty">No roles here yet</div>'}</div>`).join('')}catch(e){}}
async function setStage(id,stage){try{await api(`/applications/${id}`,{method:'PATCH',body:JSON.stringify({stage})});await loadApplications()}catch(e){toast(e.message)}}function copyAgentTask(){const x=$('agentTask');x.select();document.execCommand('copy');toast('Search task copied')}
async function analyzeJob(){const description=$('jobDescription').value.trim();if(!description){toast('Paste a job description first');return}const terms=parseList($('pSkills').value),hits=terms.filter(s=>description.toLowerCase().includes(s.toLowerCase())),score=Math.min(100,Math.round(hits.length/Math.max(1,Math.min(terms.length,8))*100));const result=`ROLE FIT: ${score}% keyword overlap\n\nMatching profile terms: ${hits.join(', ')||'none found'}\n\nCompare experience, location, salary, and work authorization manually. This is a ranking hint, not a hiring prediction.`;$('matchResult').textContent=result;$('matchResult').classList.remove('hidden');toast('Fit analysis ready')}
function makeDraft(){const context=$('copilotContext').value.trim();if(!context){toast('Add job details first');return}const kind=$('taskType').value,role=$('pRole').value,skills=$('pSkills').value,name=$('pName').value;const text=kind==='interview'?`INTERVIEW PREP\n\nPrepare verified examples for system design, agent workflow quality, evaluation, reliability, and collaboration. Use STAR structure and real metrics.\n\nRole context:\n${context.slice(0,1800)}`:kind==='outreach'?`RECRUITER MESSAGE DRAFT\n\nHi [Name],\n\nI’m interested in the [Role] at [Company], especially [specific requirement]. My background as ${role} includes ${skills}. Would you be open to sharing more about the team’s priorities?\n\nThanks,\n${name}\n\nVerify all details before sending.`:`APPLICATION PREPARATION DRAFT\n\nRole context:\n${context.slice(0,1800)}\n\nCandidate profile to emphasize: ${skills}.\n\nUse only achievements, dates, tools, and metrics from your source resume that you can verify. Add missing examples yourself before using.`;$('draftResult').textContent=text;$('draftResult').classList.remove('hidden')}
function exportData(){api('/profile').then(async p=>{const jobs=await api('/jobs');const apps=await api('/applications');const blob=new Blob([JSON.stringify({profile:p,jobs,applications:apps},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='neural-ant-backup.json';a.click();URL.revokeObjectURL(a.href)}).catch(e=>toast(e.message))}async function clearData(){if(!confirm('Delete your stored resume? This cannot be undone.'))return;try{await api('/resume',{method:'DELETE'});toast('Stored resume deleted');await loadProfile()}catch(e){toast(e.message)}}
checkSession();
